  }

  .header-actions,
  .deal-timer-card {
    align-items: flex-start;
  }
}

@media (max-width: 640px) {
  body {
    overflow-x: hidden;
  }

  .site-header,
  .hero,
  .featured-section,
  .deals-section,
  .editorial-section,
  .site-footer {
