  .hero-copy,
  .featured-section,
  .deals-section,
  .editorial-section,
  .site-footer {
    padding: 1.25rem;
  }

  .site-nav ul,
  .footer-links,
  .hero-highlights,
  .filter-group,
  .header-actions,
  .hero-actions {
    width: 100%;
