       const title = document.createElement("h3");
       title.textContent = deal.name;

       const description = document.createElement("p");
       description.textContent = deal.description;

       const currentPrice = document.createElement("span");
       currentPrice.className = "price-current";
       currentPrice.textContent = deal.currentPrice;

       const originalPrice = document.createElement("span");
       originalPrice.className = "price-original";
       originalPrice.textContent = deal.originalPrice;

       const priceGroup = document.createElement("div");
       priceGroup.className = "price-group";
       priceGroup.append(currentPrice, originalPrice);

       const meta = document.createElement("div");
       meta.className = "deal-meta";
       meta.append(priceGroup);

       const button = document.createElement("button");
       button.type = "button";
       button.textContent = "Shop offer";
       button.setAttribute("aria-label", `Shop offer: ${deal.name}`);

       card.append(createArtBlock("deal-art", deal.art), badge, title, description, meta, button);
       return card;
     }),
   );
 }

 function renderStories() {
   editorialGrid.replaceChildren(
     ...stories.map((story) => {
       const card = document.createElement("article");
       card.className = "story-card";

       const tag = document.createElement("span");
       tag.className = "story-tag";
       tag.textContent = story.tag;

       const title = document.createElement("h3");
       title.textContent = story.title;

       const excerpt = document.createElement("p");
       excerpt.textContent = story.excerpt;

       const link = document.createElement("a");
       link.href = "#";
       link.textContent = "Read story";
       link.setAttribute("aria-label", `Read story: ${story.title}`);

       card.append(createArtBlock("story-art", story.art), tag, title, excerpt, link);
       return card;
     }),
   );
 }

 function updateDealTimer() {
   const now = new Date();
   const deadline = new Date();
   deadline.setHours(23, 59, 59, 999);

